async def act(page):
    # Continue from the current page state (New Rule / Magento Admin)
    # 1) Ensure Websites and Customer Groups include all options
    try:
        # Select the single website available (Main Website)
        await page.get_by_role("listbox", name="Websites *").select_option(label="Main Website")
    except Exception:
        # Best-effort fallback: try accessing by label if role name differs
        try:
            await page.get_by_label("Websites *").select_option(label="Main Website")
        except Exception:
            pass

    try:
        # Select all customer groups so rule applies to all customers
        await page.get_by_role("listbox", name="Customer Groups *").select_option([
            "NOT LOGGED IN",
            "General",
            "Wholesale",
            "VIP Member",
            "Private Sales Member",
        ])
    except Exception:
        # Fallback: try alternate label locator
        try:
            await page.get_by_label("Customer Groups *").select_option([
                "NOT LOGGED IN",
                "General",
                "Wholesale",
                "VIP Member",
                "Private Sales Member",
            ])
        except Exception:
            pass

    # 2) Open the Actions section (it's exposed as a link in the top nav of the form)
    try:
        await page.get_by_role("link", name="Actions").click()
    except Exception:
        # fallback to other potential affordances
        try:
            await page.get_by_role("button", name="Actions").click()
        except Exception:
            pass

    # Wait a short moment for the Actions pane to render (in-page action)
    await page.wait_for_timeout(500)

    # 3) Set Apply -> Percent of product price discount
    applied = False
    apply_names_to_try = ["Apply", "Apply *"]
    for apply_name in apply_names_to_try:
        if applied:
            break
        try:
            # Try selecting by visible label first
            await page.get_by_role("combobox", name=apply_name).select_option(label="Percent of product price discount")
            applied = True
            break
        except Exception:
            try:
                # Try selecting by common internal value fallback
                await page.get_by_role("combobox", name=apply_name).select_option(value="by_percent")
                applied = True
                break
            except Exception:
                # try selecting by any label that includes 'Percent'
                try:
                    await page.get_by_role("combobox", name=apply_name).select_option(label="Percent")
                    applied = True
                    break
                except Exception:
                    pass

    # Additional fallback: search for any combobox named 'Apply' without exact
    if not applied:
        try:
            comb = page.get_by_role("combobox").filter(has=page.get_by_role("option", name="Percent of product price discount"))
            if await comb.count() > 0:
                await comb.first.select_option(label="Percent of product price discount")
                applied = True
        except Exception:
            pass

    # 4) Set Discount Amount -> 45
    discounted = False
    try:
        await page.get_by_role("textbox", name="Discount Amount").fill("45")
        discounted = True
    except Exception:
        try:
            await page.get_by_label("Discount Amount").fill("45")
            discounted = True
        except Exception:
            # try a generic textbox that contains 'Discount'
            try:
                tb = page.get_by_role("textbox").filter(has=page.get_by_role("label", name=lambda n: n and "Discount" in n))
                if await tb.count() > 0:
                    await tb.first.fill("45")
                    discounted = True
            except Exception:
                pass

    # 5) Save the rule (final action that will submit the form / navigate)
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        try:
            await page.get_by_role("button", name="Save Rule").click()
        except Exception:
            try:
                await page.get_by_role("button", name="Save and Continue Edit").click()
            except Exception:
                pass

    # Wait for any navigation or processing triggered by Save
    try:
        await page.wait_for_load_state("networkidle")
    except Exception:
        try:
            await page.wait_for_load_state("load")
        except Exception:
            # final fallback short wait
            await page.wait_for_timeout(1000)

